BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_accessibility_preferences(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,high_contrast BOOLEAN NOT NULL DEFAULT FALSE,font_scale NUMERIC(3,2) NOT NULL DEFAULT 1.00 CHECK(font_scale BETWEEN 1 AND 2),plain_language BOOLEAN NOT NULL DEFAULT FALSE,low_bandwidth BOOLEAN NOT NULL DEFAULT FALSE,preferred_format TEXT NOT NULL DEFAULT 'standard_text' CHECK(preferred_format IN('standard_text','plain_text','audio_only','captioned_video','sign_language_video','large_print')),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS mission_bridge_accessible_content_variants(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,content_version_id UUID NOT NULL REFERENCES mission_bridge_content_versions(id),format TEXT NOT NULL CHECK(format IN('standard_text','plain_text','audio_only','captioned_video','sign_language_video','large_print')),asset_url TEXT NOT NULL,transcript TEXT,caption_url TEXT,audio_description TEXT,downloadable BOOLEAN NOT NULL DEFAULT TRUE,low_bandwidth_bytes BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(content_version_id,format));
CREATE TABLE IF NOT EXISTS mission_bridge_disability_user_reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,content_version_id UUID NOT NULL REFERENCES mission_bridge_content_versions(id),reviewer_user_id TEXT NOT NULL,access_need_context TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('approved','changes_requested')),notes TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_accessible_contributors(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,role_key TEXT NOT NULL CHECK(role_key IN('author','facilitator','reviewer','leader')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,role_key));
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_accessibility_preferences','mission_bridge_accessible_content_variants','mission_bridge_disability_user_reviews','mission_bridge_accessible_contributors'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
